class Solution { public String fractionAddition(String expression){long numerator=0,denominator=1;int index=0;while(index<expression.length()){int sign=1;if(expression.charAt(index)=='+'||expression.charAt(index)=='-')sign=expression.charAt(index++)=='-'?-1:1;long value=0;while(Character.isDigit(expression.charAt(index)))value=value*10+expression.charAt(index++)-'0';index++;long divisor=0;while(index<expression.length()&&Character.isDigit(expression.charAt(index)))divisor=divisor*10+expression.charAt(index++)-'0';numerator=numerator*divisor+sign*value*denominator;denominator*=divisor;long gcd=gcd(Math.abs(numerator),denominator);numerator/=gcd;denominator/=gcd;}return numerator+"/"+denominator;}private long gcd(long a,long b){while(b!=0){long value=a%b;a=b;b=value;}return a;} }
